mapper.select:
SELECT a.* FROM sys_log a WHERE a.create_date BETWEEN #{beginDate} AND #{endDate}
AND a.title LIKE '%'||#{title}||'%' '%'+#{title}+'%' CONCAT('%', #{title}, '%')
AND a.create_by = #{createBy}
AND a.request_uri LIKE '%'||#{requestUri}||'%' '%'+#{requestUri}+'%' CONCAT('%', #{requestUri}, '%')
AND a.state = 0
ORDER BY a.create_date DESC

SELECT 
	a.*
FROM sys_cfg_operation_log a
WHERE a.create_date BETWEEN #{beginDate} AND #{endDate}

	AND a.function_name=#{functionName}


	AND a.create_by = #{createBy}


	AND a.operation=#{operation}


	AND a.state = 0

ORDER BY a.create_date DESC
